// Assemble the OpenRouter payload. The Merge node passes through either
// the weather result (location granted) or the webhook data (no location).
const hook = $('Webhook (analyze)').first().json;
const source = $('Merge').first().json;

const hasWeather =
  source && source.main && (source.main.temp !== undefined || source.main.humidity !== undefined);
const temp = hasWeather ? source.main.temp : 'N/A';
const humidity = hasWeather ? source.main.humidity : 'N/A';

return [{
  json: {
    base64Image: hook.base64Image || '',
    imageUrl: hook.imageUrl || '',
    scanId: hook.scanId || '',
    temp: temp,
    humidity: humidity,
    lat: hook.lat || null,
    lng: hook.lng || null
  }
}];

